import openpyxl
from openpyxl.worksheet.formula import ArrayFormula
p1='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_46495_answer_template_2272_golden.xlsx'
p2='/mnt/hhq/data/answer_files/3_46495_answer.xlsx'
def dump(p):
    wb=openpyxl.load_workbook(p, data_only=False)
    ws=wb['Sheet1']
    out={}
    for r in range(1,21):
        for col in 'ABCDEFG':
            c=ws[f'{col}{r}']
            v=c.value
            if isinstance(v, ArrayFormula):
                out[f'{col}{r}']=('AF', v.ref, v.text)
            else:
                out[f'{col}{r}']=v
    return out
d1=dump(p1); d2=dump(p2)
for k in sorted(set(d1)|set(d2)):
    if d1.get(k)!=d2.get(k):
        print('DIFF', k, repr(d1.get(k)), repr(d2.get(k)))
print('done')
